const liczniki = new WeakMap();

function policzWywolania(fn) {
  const opakowana = (...args) => {
    liczniki.set(opakowana, liczniki.get(opakowana) + 1);
    return fn(...args);
  };
  liczniki.set(opakowana, 0);
  return opakowana;
}

const ileRazy = fn => liczniki.get(fn);

const dodaj = policzWywolania((a, b) => a + b);
