const cache = new WeakMap();

function analiza(obiekt) {
  if (cache.has(obiekt)) return cache.get(obiekt);
  console.log("liczenie");
  const suma = Object.values(obiekt).reduce((a, b) => a + b, 0);
  cache.set(obiekt, suma);
  return suma;
}

const dane = { a: 1, b: 2, c: 3 };
console.log(analiza(dane)); // liczenie, potem 6
console.log(analiza(dane)); // 6 (z cache)

let obiekt = { duze: "dane" };
const slaba = new WeakMap([[obiekt, 1]]);
const silna = new Map([[obiekt, 1]]);

obiekt = null;
console.log(silna.size); // -> 1
// W Map obiekt-klucz nadal jest trzymany "silnie" - nie zostanie usuniety z pamieci.
// W WeakMap referencja jest "slaba" - garbage collector moze zwolnic obiekt (i wpis).
// Tego drugiego nie da sie zaobserwowac deterministycznie, bo WeakMap nie ma size.

const meta = new WeakMap();

function ustaw(obiekt, klucz, wartosc) {
  if (!meta.has(obiekt)) meta.set(obiekt, new Map());
  meta.get(obiekt).set(klucz, wartosc);
}

const pobierz = (obiekt, klucz) => meta.get(obiekt)?.get(klucz);

const a = { id: 1 };
const b = { id: 2 };
ustaw(a, "kolor", "czerwony");
ustaw(b, "kolor", "niebieski");

console.log(pobierz(a, "kolor"), pobierz(b, "kolor")); // -> czerwony niebieski
console.log(pobierz(a, "rozmiar"));                    // -> undefined

function maCykl(obiekt, odwiedzone = new WeakSet()) {
  if (typeof obiekt !== "object" || obiekt === null) return false;
  if (odwiedzone.has(obiekt)) return true;
  odwiedzone.add(obiekt);
  return Object.values(obiekt).some(w => maCykl(w, odwiedzone));
}

const a = { nazwa: "a" };
a.ja = a;

console.log(maCykl(a));                      // -> true
console.log(maCykl({ x: { y: { z: 1 } } })); // -> false

